// P&ID view models against the prototype's own render values (pid.golden.json, generated by
// scripts/proto-golden-pid.ts from design lines 3096–5239, renderValsEN and renderVals in French) on the seeded
// in-memory database (src/server/dal/pid.ts), in EN and FR: KPI tiles, the drawing card, validation steps, chips,
// scope segment, the tag register (default, per chip, per scope, searches), the overlay table, every tag drawer, the
// template labels. Deliberate deviations are listed in DEVIATIONS and asserted explicitly.
import { beforeAll, describe, expect, it } from 'vitest';
import { makeT, type Lang } from '@/i18n/translate';
import { setDb } from '@/server/db/client';
import { openDatabase } from '@/server/db/open';
import { getPidValidation, pidCandidates, type PidValidation } from '@/server/dal/pid';
import GOLD from './pid.golden.json';
import { DEFAULT_PID_STATE, type PidState } from './links';
import { pidScreenView, pidTagDrawerView } from './model';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = GOLD as any;
const LANGS: Lang[] = ['en', 'fr'];
const CODE = 'HLT-026';
let DATA: PidValidation;

/**
 * Deliberate deviations from the prototype's French: the drawing state of the KPI sub-line is translated (the prototype
 * left "Under review" in English).
 */
const DEVIATIONS: [string, string][] = [['4 feuilles · Under review · 12 sept. 2026', '4 feuilles · En revue · 12 sept. 2026']];
const fix = (lang: Lang, s: string) => (lang === 'fr' ? DEVIATIONS.reduce((x, [a, b]) => (x === a ? b : x), s) : s);
/**
 * R-148 (NEW-D1-2): a tag description is shown as typed — its exact French entry or the stored text, never the prototype's
 * partial translation ("Safety PLC — E-stop loop" was shown half translated as "Automate sécurité — E-stop loop").
 */
const DESC_AS_TYPED: Record<string, string> = { 'Automate sécurité — E-stop loop': 'Safety PLC — E-stop loop' };
const descFix = (lang: Lang, s: string) => (lang === 'fr' ? (DESC_AS_TYPED[s] ?? s) : s);
const LO = 'var(--color-accent-300)';
const OK = 'var(--color-text)';

beforeAll(async () => {
  setDb(await openDatabase());
  DATA = (await getPidValidation(CODE))!;
}, 60_000);

const screen = (lang: Lang, state: Partial<PidState> = {}) =>
  pidScreenView({ code: CODE, data: DATA, state: { ...DEFAULT_PID_STATE, ...state }, docHref: '/projects/HLT-026/documents?doc=PID-HLT-026' }, makeT(lang), lang);

describe('P&ID screen — EN and FR', () => {
  it.each(LANGS)('%s: KPI tiles', (lang) => {
    expect(screen(lang).kpis).toEqual(G[lang].kpis.map((k: any) => ({ ...k, value: String(k.value), sub: fix(lang, k.sub) })));
  });

  it.each(LANGS)('%s: status chips and scope segment', (lang) => {
    const v = screen(lang);
    expect(v.chips.map((c) => ({ label: c.label, count: String(c.count) }))).toEqual(G[lang].chips.map((c: any) => ({ label: c.label, count: c.count })));
    expect(v.filter).toBe('all');
    expect(v.scopes.map((o) => o.label)).toEqual(G[lang].scopeSeg.map((o: any) => o.label));
    expect(v.chips.map((c) => c.href)).toEqual([
      '/projects/HLT-026/pid', '/projects/HLT-026/pid?status=linked', '/projects/HLT-026/pid?status=unmapped', '/projects/HLT-026/pid?status=part_not_validated',
      '/projects/HLT-026/pid?status=part_outdated', '/projects/HLT-026/pid?status=client',
    ]);
    expect(v.scopes.map((o) => o.href)).toEqual(['/projects/HLT-026/pid', '/projects/HLT-026/pid?scope=keystone', '/projects/HLT-026/pid?scope=overlay', '/projects/HLT-026/pid?scope=client']);
  });

  it.each(LANGS)('%s: validation steps', (lang) => {
    expect(screen(lang).steps).toEqual(G[lang].steps.map((s: any) => ({ label: s.label, whoDate: `${s.who} · ${s.date}`, dot: s.dot, color: s.color, state: s.state, tagClass: s.tagClass })));
  });

  it.each(LANGS)('%s: tag register cells', (lang) => {
    const v = screen(lang);
    expect(v.rows.map((r) => ({
      tag: r.tag, desc: r.desc, kind: r.kind, scope: r.scope, scopeClass: r.scopeClass, refText: r.refText, partName: r.partName, status: r.status, tagClass: r.statusClass,
      actText: r.actText, plcText: r.plc.text, plcTag: r.plc.asTag, plcPlain: !r.plc.asTag, plcClass: r.plc.tagClass, fbWarn: r.feedback.tone === 'warn', fbText: r.feedback.text,
      fbColor: r.feedback.tone === 'warn' ? LO : r.feedback.tone === 'text' ? OK : 'var(--color-neutral-500)', tagColor: r.selected ? LO : OK,
    }))).toEqual(G[lang].rows.map((r: any) => ({ ...Object.fromEntries(Object.entries(r).filter(([k]) => k !== 'ref' && k !== 'hasPart')), desc: descFix(lang, r.desc) })));
    expect(screen(lang, { tag: 'XV-111' }).rows.map((r) => (r.selected ? LO : OK))).toEqual(G[lang].selectedTagColor);
    expect(v.empty).toBeNull();
  });

  it.each(LANGS)('%s: filters, scopes, searches and combinations (URL state)', (lang) => {
    const tags = (state: Partial<PidState>) => screen(lang, state).rows.map((r) => r.tag);
    const codeOf: Record<string, PidState['status']> = {
      Linked: 'linked', Unmapped: 'unmapped', 'Not in BOM': 'not_in_bom', 'Part not validated': 'part_not_validated', 'Part outdated': 'part_outdated', 'Part obsolete': 'part_obsolete', Client: 'client',
    };
    for (const [label, f] of Object.entries(G.en.filters as Record<string, { tags: string[] }>)) expect(tags({ status: codeOf[label] }), label).toEqual(f.tags);
    for (const [label, f] of Object.entries(G.en.scopes as Record<string, { tags: string[] }>)) expect(tags({ scope: label.toLowerCase() as PidState['scope'] }), label).toEqual(f.tags);
    for (const [q, ids] of Object.entries(G.en.searches as Record<string, string[]>)) expect(tags({ q }), q).toEqual(ids);
    expect(tags({ status: 'unmapped', scope: 'overlay' })).toEqual(G.en.combos['Unmapped|Overlay']);
    expect(tags({ status: 'linked', scope: 'keystone', q: 'vfd' })).toEqual(G.en.combos['Linked|Keystone|vfd']);
    const none = screen(lang, { status: 'part_outdated', q: 'zzz' });
    expect([none.rows, none.empty]).toEqual([[], lang === 'fr' ? 'Aucun tag ne correspond' : 'No tag matches']);
    // Links keep the filters; the selected row's link closes the drawer.
    const sel = screen(lang, { status: 'unmapped', q: 'transmitter', tag: 'TT-102' });
    expect(sel.rows.map((r) => [r.tag, r.href])).toEqual([
      ['TT-102', '/projects/HLT-026/pid?status=unmapped&q=transmitter'],
      ['PT-201', '/projects/HLT-026/pid?status=unmapped&q=transmitter&tag=PT-201'],
    ]);
  });

  it('fr: the search also matches the French text the viewer reads', () => {
    expect(screen('fr', { q: 'manquant' }).rows.map((r) => r.tag)).toEqual(['XV-111']);
    // SIS-001's description ("Safety PLC — E-stop loop") is shown as typed (R-148): it no longer reads "Automate sécurité".
    expect(screen('fr', { q: 'automate sécurité' }).rows.map((r) => r.tag)).toEqual(['LSH-101', 'ZS-310', 'ESD-001', 'WS-001', 'LIDAR-001', 'FD-001']);
    expect(screen('en', { q: 'manquant' }).rows).toEqual([]);
  });

  it.each(LANGS)('%s: overlay table', (lang) => {
    expect(screen(lang).overlay.map((r) => ({ tag: r.tag, desc: r.desc, scope: r.scope, scopeClass: r.scopeClass, refText: r.refText, status: r.status, tagClass: r.statusClass })))
      .toEqual(G[lang].overlay);
    expect(screen(lang, { status: 'linked' }).overlay[0].href).toBe('/projects/HLT-026/pid?status=linked&tag=LT-101');
  });

  it.each(LANGS)('%s: drawing card', (lang) => {
    const d = screen(lang).drawing;
    expect(d).toEqual({
      title: lang === 'fr' ? 'Schéma PID' : 'P&ID drawing',
      documentNumber: 'PID-HLT-026',
      rev: lang === 'fr' ? 'rév. C' : 'rev C',
      docHref: '/projects/HLT-026/documents?doc=PID-HLT-026',
      docTitle: lang === 'fr' ? 'Codex · rév. D · Diffusé' : 'Codex · rev D · Released',
      placeholder: G.labels['Drop the P&ID (PDF / PNG) — sheets 1–4'] && (lang === 'fr' ? G.labels['Drop the P&ID (PDF / PNG) — sheets 1–4'] : 'Drop the P&ID (PDF / PNG) — sheets 1–4'),
      // A-9 (R-109): declared deviation — the seed's tags come from rev C while Codex has rev D Released (the gap the owner
      // described): a banner, absent from the prototype, suggests re-importing rev D.
      gap: {
        ahead: true, suggestedRevision: 'D',
        text: lang === 'fr'
          ? 'Codex a la rév. D de ce PID (Diffusé) — les tags viennent de la rév. C. Réimportez les tags de la rév. D.'
          : 'Codex has rev D of this P&ID (Released) — the tags come from rev C. Re-import the tags of rev D.',
      },
    });
  });
});

describe('P&ID tag drawer — EN and FR', () => {
  it.each(LANGS)('%s: every tag — record, candidates, notices, actions', async (lang) => {
    const t = makeT(lang);
    for (const tag of DATA.tags) {
      const g = G[lang].drawers[tag.tag];
      const cands = (await pidCandidates(CODE, tag.tag)).rows;
      const d = pidTagDrawerView({ code: CODE, data: DATA, tag, candidates: cands, state: { ...DEFAULT_PID_STATE, tag: tag.tag }, bomHrefOf: (ref) => `/projects/HLT-026/bom?part=${ref}` }, t, lang);
      expect([d.head, d.title, d.scope, d.scopeClass, d.status, d.statusClass], tag.tag).toEqual([`${g.tag} · ${g.kind}`, descFix(lang, g.desc), g.scope, g.scopeClass, g.status, g.tagClass]);
      expect(d.record.map((r) => [r.k, r.v]), tag.tag).toEqual(g.meta);
      expect([d.isClient, d.fbWarn, d.candidates != null, d.partHref != null, d.bomHref != null], tag.tag).toEqual([g.isClient, g.fbWarn, g.canMap, g.hasPart, g.notInBom]);
      // E-6 (R-108): the prototype's candidates are the first "In the BOM" rows of the catalogue search (their part status kept).
      if (d.candidates) expect(d.candidates.filter((c) => c.inBom).slice(0, 8).map((c) => ({ ref: c.ref, name: c.name, status: c.partStatus })), tag.tag).toEqual(g.candidates.map((c: any) => ({ ref: c.ref, name: c.name, status: c.status })));
      expect(d.canUnlink, tag.tag).toBe(tag.scope !== 'client' && !!tag.partRef);
      expect(d.closeHref).toBe('/projects/HLT-026/pid');
    }
  });

  it('links: reference → project BOM line, activity → plan drawer, Part record → part drawer over the screen (back to the tag)', async () => {
    const tag = DATA.tags.find((x) => x.tag === 'LT-101')!;
    const d = pidTagDrawerView(
      { code: CODE, data: DATA, tag, candidates: [], state: { ...DEFAULT_PID_STATE, scope: 'overlay', tag: 'LT-101' }, bomHrefOf: (ref) => `/projects/HLT-026/bom?part=${ref}` },
      makeT('en'),
      'en',
    );
    expect(d.record.filter((r) => r.href).map((r) => [r.k, r.href])).toEqual([
      ['Reference', '/projects/HLT-026/bom?part=EL-PLC-S7'],
      ['Activity', '/projects/HLT-026/plan?act=A1410'],
    ]);
    expect([d.partHref, d.closeHref]).toEqual(['/projects/HLT-026/pid?scope=overlay&tag=LT-101&part=EL-PLC-S7', '/projects/HLT-026/pid?scope=overlay']);
    // An unmapped tag: no reference link, no Part record.
    const tt = pidTagDrawerView({ code: CODE, data: DATA, tag: DATA.tags.find((x) => x.tag === 'TT-102')!, candidates: [], state: DEFAULT_PID_STATE, bomHrefOf: (r) => r }, makeT('en'), 'en');
    expect([tt.record[0].href, tt.partHref, tt.canUnlink]).toEqual([undefined, null, false]);
  });
});

describe('template labels', () => {
  it('every template label of the screen translates to the prototype French', () => {
    const t = makeT('fr');
    for (const [en, fr] of Object.entries(G.labels as Record<string, string>)) expect(t(en), en).toBe(fr);
    const extra = { ...(G.extra as Record<string, string>) };
    // The prototype's import toast kept "rev" and the fixed numbers; the rebuild builds it (src/features/pid/i18n.ts).
    delete extra['27 tags · rev E imported · 3 new · 1 updated'];
    delete extra['27 tags imported · 3 new · 1 updated'];
    for (const [en, fr] of Object.entries(extra)) expect(t(en), en).toBe(fr);
  });
});
